// src/core/supervisor/supervisorTransitions.ts
// BOWCON V4.0 — MS-1.3.35: REAL BOWCON SUPERVISORY AUTONOMOUS RECOVERY & HUMAN GOVERNANCE RUNTIME
//
// Authoritative Supervisor State Transition Matrix and invariant guards.
export const VALID_SUPERVISOR_TRANSITIONS = {
    INITIALIZING: ['OBSERVING', 'SAFE_STOP', 'STOPPED'],
    OBSERVING: ['HEALTHY', 'ANOMALY_DETECTED', 'DIAGNOSING', 'RECOVERY_PLANNING', 'POLICY_EVALUATION', 'SAFE_STOP', 'STOPPED'],
    HEALTHY: ['OBSERVING', 'ANOMALY_DETECTED', 'DIAGNOSING', 'RECOVERY_PLANNING', 'POLICY_EVALUATION', 'WAITING_FOR_HUMAN', 'RECOVERING', 'SAFE_STOP', 'STOPPED'],
    ANOMALY_DETECTED: ['DIAGNOSING', 'RECOVERY_PLANNING', 'OBSERVING', 'SAFE_STOP', 'STOPPED'],
    DIAGNOSING: ['RECOVERY_PLANNING', 'OBSERVING', 'HEALTHY', 'ESCALATED', 'SAFE_STOP', 'STOPPED'],
    RECOVERY_PLANNING: ['POLICY_EVALUATION', 'OBSERVING', 'HEALTHY', 'SAFE_STOP', 'STOPPED'],
    POLICY_EVALUATION: ['WAITING_FOR_HUMAN', 'AUTHORIZED', 'RECOVERING', 'ESCALATED', 'OBSERVING', 'HEALTHY', 'SAFE_STOP', 'STOPPED'],
    WAITING_FOR_HUMAN: ['AUTHORIZED', 'OBSERVING', 'HEALTHY', 'ESCALATED', 'SAFE_STOP', 'STOPPED'],
    AUTHORIZED: ['RECOVERING', 'WAITING_FOR_HUMAN', 'POLICY_EVALUATION', 'OBSERVING', 'HEALTHY', 'SAFE_STOP', 'STOPPED'],
    RECOVERING: ['VERIFYING', 'RECOVERY_FAILED', 'SAFE_STOP', 'STOPPED'],
    VERIFYING: ['RECOVERY_SUCCEEDED', 'RECOVERY_FAILED', 'SAFE_STOP', 'STOPPED'],
    RECOVERY_SUCCEEDED: ['OBSERVING', 'HEALTHY', 'SAFE_STOP', 'STOPPED'],
    RECOVERY_FAILED: ['POLICY_EVALUATION', 'RECOVERING', 'ESCALATED', 'OBSERVING', 'HEALTHY', 'SAFE_STOP', 'STOPPED'],
    ESCALATED: ['WAITING_FOR_HUMAN', 'RECOVERING', 'OBSERVING', 'HEALTHY', 'SAFE_STOP', 'STOPPED'],
    SAFE_STOP: ['OBSERVING', 'HEALTHY', 'INITIALIZING', 'STOPPED'],
    STOPPED: ['INITIALIZING'],
};
export function isValidSupervisorTransition(from, to) {
    if (from === to)
        return true;
    // SAFE_STOP can always be entered from ANY state (USER_STOP > AUTONOMOUS_EXECUTION)
    if (to === 'SAFE_STOP')
        return true;
    const allowed = VALID_SUPERVISOR_TRANSITIONS[from];
    return allowed ? allowed.includes(to) : false;
}
export function assertValidSupervisorTransition(from, to, context) {
    if (!isValidSupervisorTransition(from, to)) {
        throw new Error(`INVALID_SUPERVISOR_TRANSITION: Cannot transition supervisor from "${from}" to "${to}"${context ? ` (context: ${context})` : ''}.`);
    }
}
